//! Falabichos client: a thin Bevy shell around the engine-agnostic `falabichos-game` crate.
//!
//! Bevy provides the window, the GPU texture the 240x160 frame is uploaded to, keyboard / gamepad /
//! touch input, audio output and the app lifecycle. All game logic lives in `falabichos-game`.
//!
//! Entry points: `main()` on desktop, `android_main` (generated by `#[bevy_main]`) on Android, and
//! `main_rs` on iOS (called from the Xcode project's `main.m`).

// The only `unsafe` in the workspace: the `#[no_mangle]` entry points that Android and iOS require.
#![cfg_attr(any(target_os = "android", target_os = "ios"), allow(unsafe_code))]

mod audio;
mod cli;
mod controls;
mod display;
mod platform;

use audio::{MusicMarker, Sound};
use bevy::audio::{AudioSink, AudioSource};
use bevy::input::ButtonState;
use bevy::input::keyboard::{Key, KeyboardInput};
use bevy::input::touch::Touches;
use bevy::prelude::*;
use bevy::render::view::screenshot::{Screenshot, save_to_disk};
use bevy::window::{AppLifecycle, MonitorSelection, PrimaryWindow, WindowMode};
use display::{Frame, SafeInsets};
use falabichos_assets::Assets as AssetBundle;
use falabichos_game::touch_art::TouchLayout;
use falabichos_game::{FileStorage, Game, GameConfig, GameEvent, Input, LOGICAL_H, LOGICAL_W};
use std::sync::Arc;

#[derive(Resource)]
struct GameRes(Game);

#[derive(Resource, Default)]
struct Latch {
    input: Input,
    typed: String,
    backspace: bool,
    enter: bool,
}

#[derive(Resource)]
struct Opts {
    args: cli::Args,
    touch_ui: bool,
    smoke_tick: u32,
    shot_taken: bool,
}

#[bevy::prelude::bevy_main]
pub fn main() {
    let args = match cli::parse(std::env::args().skip(1)) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("error: {e}\n{}", cli::HELP);
            std::process::exit(2);
        }
    };
    if args.help {
        print!("{}", cli::HELP);
        return;
    }
    if args.version {
        println!("falabichos {}", falabichos_game::VERSION);
        return;
    }
    let assets: Arc<AssetBundle> = Arc::new(match &args.assets_dir {
        Some(dir) => AssetBundle::from_dir(dir).unwrap_or_else(|e| {
            eprintln!("cannot read assets from {}: {e}", dir.display());
            std::process::exit(2);
        }),
        None => AssetBundle::from_env_or_embedded(),
    });
    if args.headless_sim {
        match falabichos_game::sim::run_all(assets) {
            Ok(lines) => {
                lines.iter().for_each(|l| println!("{l}"));
                return;
            }
            Err(e) => {
                eprintln!("HEADLESS SIMULATION FAILED: {e}");
                std::process::exit(1);
            }
        }
    }
    if let Some(dir) = &args.screenshots {
        match falabichos_game::sim::screenshots(assets, dir.clone()) {
            Ok(n) => {
                println!("wrote {n} screenshots to {}", dir.display());
                return;
            }
            Err(e) => {
                eprintln!("screenshot run failed: {e}");
                std::process::exit(1);
            }
        }
    }
    run_window(args, assets);
}

fn run_window(args: cli::Args, assets: Arc<AssetBundle>) {
    let mobile = platform::is_mobile();
    let storage = FileStorage::new(platform::data_dir(&args));
    let config = GameConfig {
        can_quit: !mobile,
        touch: mobile || args.touch,
        seed: None,
    };
    let mut game = match Game::new(assets.clone(), Box::new(storage), config) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("could not start the game: {e}");
            std::process::exit(1);
        }
    };
    let fullscreen = args.fullscreen || game.settings.fullscreen;
    game.settings.fullscreen = fullscreen;
    let touch_ui = mobile || args.touch;
    let window = Window {
        title: "Falabichos".into(),
        resolution: (960, 640).into(),
        resizable: true,
        mode: if fullscreen {
            WindowMode::BorderlessFullscreen(MonitorSelection::Current)
        } else {
            WindowMode::Windowed
        },
        ..default()
    };
    App::new()
        .insert_resource(ClearColor(Color::BLACK))
        .insert_resource(Time::<Fixed>::from_hz(60.0))
        .insert_resource(GameRes(game))
        .insert_resource(Sound::new(assets))
        .insert_resource(Latch::default())
        .insert_resource(SafeInsets(platform::safe_insets()))
        .insert_resource(Opts {
            args,
            touch_ui,
            smoke_tick: 0,
            shot_taken: false,
        })
        .add_plugins(
            DefaultPlugins
                .set(WindowPlugin {
                    primary_window: Some(window),
                    ..default()
                })
                .set(ImagePlugin::default_nearest()),
        )
        .add_systems(Startup, setup)
        .add_systems(
            Update,
            (
                collect_keyboard,
                collect_touch,
                tick_when_needed_draw,
                display::layout_frame,
                apply_events,
                lifecycle,
                autoquit,
                window_shot,
                toggle_fullscreen_key,
            )
                .chain(),
        )
        .add_systems(FixedUpdate, tick_game)
        .add_systems(Last, on_exit)
        .run();
}

fn setup(mut commands: Commands, mut images: ResMut<Assets<Image>>, game: Res<GameRes>, opts: Res<Opts>) {
    let frame = display::frame_resource(&mut images);
    display::spawn_display(&mut commands, &mut images, &frame, game.0.art(), opts.touch_ui);
    commands.insert_resource(frame);
}

fn collect_keyboard(
    keys: Res<ButtonInput<KeyCode>>,
    mut events: MessageReader<KeyboardInput>,
    mut latch: ResMut<Latch>,
    game: Res<GameRes>,
) {
    let wants_text = game.0.wants_text_input();
    // remember key presses that start and end between two fixed ticks
    let just = |k: KeyCode| keys.just_pressed(k);
    let pressed = controls::map_keys(&just, wants_text);
    controls::merge(&mut latch.input, &pressed);
    for e in events.read() {
        if e.state != ButtonState::Pressed {
            continue;
        }
        if wants_text {
            match &e.logical_key {
                Key::Character(s) => latch.typed.push_str(s.as_str()),
                Key::Space => latch.typed.push(' '),
                Key::Backspace => latch.backspace = true,
                Key::Enter => latch.enter = true,
                _ => {}
            }
        }
    }
}

fn collect_touch(
    touches: Res<Touches>,
    mouse: Res<ButtonInput<MouseButton>>,
    windows: Query<&Window, With<PrimaryWindow>>,
    insets: Res<SafeInsets>,
    opts: Res<Opts>,
    mut latch: ResMut<Latch>,
) {
    if !opts.touch_ui {
        return;
    }
    let Ok(window) = windows.single() else { return };
    let layout = TouchLayout::compute(window.width(), window.height(), insets.0, window.scale_factor());
    let mut points: Vec<(f32, f32)> = touches.iter().map(|t| (t.position().x, t.position().y)).collect();
    if mouse.pressed(MouseButton::Left)
        && let Some(p) = window.cursor_position()
    {
        points.push((p.x, p.y));
    }
    let held = layout.read(&points);
    controls::merge(&mut latch.input, &held);
    // tap anywhere else on the game screen to advance (dialogue, feedback)
    let mut taps: Vec<(f32, f32)> = touches
        .iter_just_pressed()
        .map(|t| (t.position().x, t.position().y))
        .collect();
    if mouse.just_pressed(MouseButton::Left)
        && let Some(p) = window.cursor_position()
    {
        taps.push((p.x, p.y));
    }
    for (x, y) in taps {
        let on_control = [layout.dpad, layout.a, layout.b, layout.menu, layout.hint]
            .iter()
            .any(|r| r.contains(x, y));
        if !on_control {
            latch.input.a = true;
        }
    }
}

fn tick_game(
    keys: Res<ButtonInput<KeyCode>>,
    gamepads: Query<&Gamepad>,
    mut latch: ResMut<Latch>,
    mut game: ResMut<GameRes>,
    mut opts: ResMut<Opts>,
) {
    let wants_text = game.0.wants_text_input();
    let held = |k: KeyCode| keys.pressed(k);
    let mut input = controls::map_keys(&held, wants_text);
    for gp in gamepads.iter() {
        controls::merge(&mut input, &controls::read_gamepad(gp));
    }
    // fold in presses that happened between ticks, then clear the latch
    let l = std::mem::take(&mut *latch);
    let mut latched = l.input;
    latched.typed = l.typed;
    latched.backspace = l.backspace;
    latched.enter = l.enter;
    controls::merge(&mut input, &latched);
    if opts.args.smoke {
        opts.smoke_tick += 1;
        controls::merge(&mut input, &smoke_input(opts.smoke_tick));
    }
    game.0.tick(&input);
}

/// Deterministic pseudo-random key presses for the CI boot test.
fn smoke_input(t: u32) -> Input {
    let mut i = Input::default();
    if t % 45 < 3 {
        i.a = true;
    }
    if t > 400 {
        let seg = (t / 24) % 8;
        match seg {
            0 | 1 => i.down = true,
            2 => i.right = true,
            3 | 4 => i.up = true,
            5 => i.left = true,
            _ => {}
        }
    }
    i
}

fn tick_when_needed_draw(game: ResMut<GameRes>, mut frame: ResMut<Frame>, mut images: ResMut<Assets<Image>>) {
    if frame.drawn_tick == game.0.tick {
        return;
    }
    frame.drawn_tick = game.0.tick;
    let mut canvas = std::mem::replace(&mut frame.canvas, falabichos_media::Canvas::new(0, 0));
    if canvas.w != LOGICAL_W || canvas.h != LOGICAL_H {
        canvas = falabichos_media::Canvas::new(LOGICAL_W, LOGICAL_H);
    }
    game.0.draw(&mut canvas);
    if let Some(mut img) = images.get_mut(&frame.handle) {
        img.data = Some(canvas.px.clone());
    }
    frame.canvas = canvas;
}

#[allow(clippy::too_many_arguments)]
fn apply_events(
    mut commands: Commands,
    mut game: ResMut<GameRes>,
    mut sound: ResMut<Sound>,
    mut sources: ResMut<Assets<AudioSource>>,
    mut sinks: Query<&mut AudioSink, With<MusicMarker>>,
    mut windows: Query<&mut Window, With<PrimaryWindow>>,
    mut exit: MessageWriter<AppExit>,
) {
    for ev in game.0.take_events() {
        match &ev {
            GameEvent::Quit => {
                exit.write(AppExit::Success);
            }
            GameEvent::Fullscreen(on) => {
                if let Ok(mut w) = windows.single_mut() {
                    w.mode = if *on {
                        WindowMode::BorderlessFullscreen(MonitorSelection::Current)
                    } else {
                        WindowMode::Windowed
                    };
                }
            }
            GameEvent::SettingsChanged => sound.apply_volume(&mut sinks, &game.0.settings),
            _ => sound.handle(&ev, &mut commands, &mut sources, &game.0.settings),
        }
    }
}

fn lifecycle(mut events: MessageReader<AppLifecycle>, mut game: ResMut<GameRes>) {
    for e in events.read() {
        if matches!(e, AppLifecycle::WillSuspend | AppLifecycle::Suspended) {
            game.0.on_suspend();
        }
    }
}

fn on_exit(mut exit: MessageReader<AppExit>, mut game: ResMut<GameRes>) {
    if exit.read().next().is_some() {
        game.0.on_suspend();
    }
}

fn window_shot(mut commands: Commands, time: Res<Time>, mut opts: ResMut<Opts>) {
    if opts.shot_taken {
        return;
    }
    if let Some(path) = opts.args.window_shot.clone()
        && time.elapsed_secs() > opts.args.window_shot_after
    {
        opts.shot_taken = true;
        commands
            .spawn(Screenshot::primary_window())
            .observe(save_to_disk(path));
    }
}

fn autoquit(time: Res<Time>, opts: Res<Opts>, mut exit: MessageWriter<AppExit>) {
    if let Some(s) = opts.args.autoquit
        && time.elapsed_secs() > s
    {
        exit.write(AppExit::Success);
    }
}

fn toggle_fullscreen_key(
    keys: Res<ButtonInput<KeyCode>>,
    mut windows: Query<&mut Window, With<PrimaryWindow>>,
    mut game: ResMut<GameRes>,
) {
    let alt = keys.pressed(KeyCode::AltLeft) || keys.pressed(KeyCode::AltRight);
    if (keys.just_pressed(KeyCode::F11) || (alt && keys.just_pressed(KeyCode::Enter)))
        && let Ok(mut w) = windows.single_mut()
    {
        let on = matches!(w.mode, WindowMode::Windowed);
        w.mode = if on {
            WindowMode::BorderlessFullscreen(MonitorSelection::Current)
        } else {
            WindowMode::Windowed
        };
        game.0.set_fullscreen(on);
    }
}

/// iOS entry point, called from `mobile/ios/Falabichos/main.m`.
#[cfg(target_os = "ios")]
#[unsafe(no_mangle)]
pub extern "C" fn main_rs() {
    main();
}
